@php($returns=DB::table('order_returns')->where('order_id',$order->id)->latest()->get())
<section id="returns" style="margin-top:32px"><h2>Returns & refunds</h2>@foreach($returns as $r)<article class="summary" style="margin-bottom:12px"><strong>{{ $r->number }}</strong><p>{{ $r->status }} · {{ $r->refund_status }}</p><p>{{ $r->reason }}</p><small>Refund: {{ $money($r->refund_amount) }} · excludes shipping · test only</small>@php($returnedItems=DB::table('order_return_items')->join('order_items','order_items.id','=','order_return_items.order_item_id')->where('return_id',$r->id)->select('order_items.name','order_return_items.quantity')->get())@foreach($returnedItems as $ri)<p>{{ $ri->name }} × {{ $ri->quantity }}</p>@endforeach</article>@endforeach
@if(auth()->id()===$order->user_id && in_array($order->status,['Delivered','Return requested','Return received','Partially returned']))<form method="post" action="{{ route('orders.returns',$order) }}" class="summary no-print">@csrf<input type="hidden" name="key" value="{{ (string)\Illuminate\Support\Str::uuid() }}"><h3>Request a return</h3><p>Choose quantities within 7 days of delivery. The admin will review your request and inspect the goods before recording a test refund.</p>@foreach($order->items as $item)@php($requested=DB::table('order_return_items')->join('order_returns','order_returns.id','=','order_return_items.return_id')->where('order_item_id',$item->id)->where('order_returns.status','!=','Rejected')->sum('quantity'))@if($item->quantity>$requested)<label for="return-{{ $item->id }}">{{ $item->name }} · {{ $item->quantity-$requested }} available to return</label><input id="return-{{ $item->id }}" type="number" name="quantities[{{ $item->id }}]" min="0" max="{{ $item->quantity-$requested }}" value="0">@endif @endforeach<label for="return-reason">Reason</label><textarea id="return-reason" name="reason" required minlength="5" maxlength="1000"></textarea><button>Submit return request</button></form>@endif</section>
